INSERT INTO game_endgame_definitions(owner_kind,content_version,definition_id,base_name,name,lore,lore_root,role,identity,benefit,tradeoff,power_tier,source_arm,source_desc,base_id,professions,sex,slot,level_requirement,resource_level,channel,min_level,beginner_allowed,unrestricted,native_drop_eligible,legacy_affix_pool_ready) VALUES
('unique',6,2002,'铁护头','炉耳','铁盔两侧有接炉渣的凹槽，戴上便听见极远处的锤声。第一次试盔的人循声走了一夜，天亮仍站在原来的炉前。','原型·沉重铁护头','allclasses','早期物理防护盔','物理平减 +5；生命 +6；回避防御 +4；体质 +4；魔防 +14','投入集中在物理承伤；不提供物攻、物理会心专精','transition','server/migrations/000000_init-24.sql:11725','server/migrations/000000_init-28.sql:6165',2002,31,0,2,1,1,0,0,true,false,true,true),
('unique',6,2007,'神圣头盔','铸在里面的圣字','盔外没有铭文，圣字全铸在内层。匠人以为做反了，拆模后却发现从里面看去，金属像一层很薄的光。','原型·神圣钢盔','allclasses','高精神钢盔','精神 +25；法力 +11；生命 +65；物理平减 +9；回避防御 +12','投入集中在技能续航；不提供物攻、物理会心专精','transition','server/migrations/000000_init-25.sql:10','server/migrations/000000_init-28.sql:6223',2007,31,0,2,31,4,0,0,true,false,true,true),
('unique',6,2013,'荣誉之盔','颁错的荣光','荣誉盔的金叶上没有姓名，只有一场战斗的时辰。颁奖官以为漏刻，试补姓名时，每个字都在炉火里变成原来的时辰。','原型·荣誉盔授勋','allclasses','满血防护盔','生命 +241；体质 +13；物理平减 +9；法术平减 +9；魔防 +28；回避防御 +13','固定词条提供基础提升；特性的目标、技能和血线条件仍须满足，同名特性只取最高；本件强化不放大其它装备、人物六维派生、卡片、加工或其余附加属性','highvalue','server/migrations/000000_init-25.sql:77','server/migrations/000000_init-28.sql:6292',2013,31,0,2,31,4,0,0,true,false,true,true),
('unique',6,2019,'兔子头饰','药臼边的兔耳','药童怕捣药声惊走窗外的白兔，给帽耳塞了两团棉。后来院落烧空，棉团中却滚出一粒没有焦黑的药米。','原创·玉兔捣药意象','allclasses','柔软护命头饰','生命 +78；魔防 +21；体质 +6；物理平减 +4；法术平减 +4','支付0.30U给MF，少5.5%总战斗预算；不承担BOSS速度最优承诺','transition','server/migrations/000000_init-25.sql:145','server/migrations/000000_init-28.sql:6358',2019,31,0,2,10,3,0,0,true,false,true,true),
('unique',6,2020,'趴熊帽','熊醒半夜','帽上小熊白天只是棉絮，半夜却会慢慢睁眼。铺主试过数它的眼珠，总比白天多看见一点圆光。','原型·趴熊帽','allclasses','资源型玩偶帽','法力 +54；精神 +6；生命 +36；物理平减 +4；回避防御 +6','支付0.30U给MF，少5.5%总战斗预算；不承担BOSS速度最优承诺','transition','server/migrations/000000_init-25.sql:156','server/migrations/000000_init-28.sql:6369',2020,31,0,2,10,3,0,0,true,false,true,true),
('unique',6,2023,'王冠','海图外的宝石','异国王冠共有十三枚宝石，海图上却只列十二处产地。最后那枚每次过海都会轻一点，颜色也更像深海。','原型·异族宝石王冠','allclasses','45级王冠的宝石魔防身份升为圣暗双抗小高货；实际物防白字小，不把冠位改成重甲。','魔防 +62；生命 +331；法术平减 +8；精神 +12；异常抵抗 +9','单系投资只提升匹配的真实伤害包；敌人不匹配时不是全能增伤/减伤','highvalue','server/migrations/000000_init-25.sql:192','server/migrations/000000_init-28.sql:6405',2023,31,0,2,45,5,0,0,true,false,true,true),
('unique',6,2024,'帝皇之冠','垂旒问价','戏班用碎琉璃穿成帝冠，演天庭断案时总缺一颗。班主说那颗借给卖饼的婆婆当了药钱，神仙应当不会计较。','原型·帝皇冠仿玉皇造型','allclasses','45级帝冠的问价与蓄炁身份承担高MF小高货，减少纯战斗额外预算；不附加全技能。','法力 +210；精神 +14；生命 +70；物理平减 +10；回避防御 +14','支付0.75U给MF，少11.5%总战斗预算；不承担BOSS速度最优承诺','highvalue','server/migrations/000000_init-25.sql:203','server/migrations/000000_init-28.sql:6416',2024,31,0,2,45,5,0,0,true,false,true,true),
('unique',6,2035,'包袱头','结风','包袱头裹到鼻下，结里却存着一阵山风。解开时铺中的烛火同时向东，只有门外树叶仍朝着西边摇动。','原型·包袱头包至鼻下','allclasses','精神过渡头巾','精神 +6；法力 +27；生命 +31；物理平减 +4；回避防御 +4','投入集中在技能续航；不提供物攻、物理会心专精','transition','server/migrations/000000_init-25.sql:327','server/migrations/000000_init-28.sql:6540',2035,31,0,2,6,2,0,0,true,false,true,true),
('unique',6,2036,'包子头','棉中滚钱','包子帽从第三次蒸煮后就不断冒热气，里头却从无馅料。厨子剖开一个，听见一枚小铜钱在棉中滚动。','原型·包子头冒蒸气','allclasses','低级法力帽','法力 +45；精神 +4；生命 +30；物理平减 +4；回避防御 +4','支付0.20U给MF，少3.6%总战斗预算；不承担BOSS速度最优承诺','transition','server/migrations/000000_init-25.sql:338','server/migrations/000000_init-28.sql:6551',2036,31,0,2,6,2,0,0,true,false,true,true),
('unique',6,2037,'枪手帽','帽檐刻星','舶来帽檐打着六个小孔，星光穿过时在桌上拼出陌生港口。航海者把帽倒过来，港口便像潮水一样散去。','原型·枪手帽','allclasses','初期准确饰物','命中 +5；双端物攻 +2；力量 +4；物理会心bp +143；生命 +31','投入集中在物理输出；不提供法攻、法术会心专精','transition','server/migrations/000000_init-25.sql:349','server/migrations/000000_init-28.sql:6562',2037,31,0,2,1,5,0,0,true,false,true,true),
('unique',6,2038,'海盗帽','畏井牙','海盗帽里缝着一枚不知何兽的牙，遇到淡水会轻轻打颤。卖帽人特意嘱咐，不可把它带到井边。','原型·海盗遗帽','allclasses','早期魔防帽','魔防 +18；生命 +124；法术平减 +4；精神 +4；异常抵抗 +6','投入集中在法术承伤；不提供物攻、物理会心专精','transition','server/migrations/000000_init-25.sql:360','server/migrations/000000_init-28.sql:6573',2038,31,0,2,1,5,0,0,true,false,true,true),
('unique',6,2039,'新郎彩冠','误了吉时','迎亲队在山口等到灯笼烧尽，新郎才背着落水的摆渡人回来。彩冠被河泥压坏，红绸却一寸也没有丢。','原创·婚冠与渡人','allclasses','救急仪式冠','精神 +5；法力 +69；生命 +31；魔防 +14；异常抵抗 +6','固定词条提供基础提升；特性的目标、技能和血线条件仍须满足，同名特性只取最高；男性可穿限制保留；同档对应另一性别有独立可用路线','transition','server/migrations/000000_init-25.sql:371','server/migrations/000000_init-28.sql:6586',2039,31,1,2,1,5,0,0,true,false,true,true),
('unique',6,2040,'新娘彩冠','镜凤','婚冠的珠串应当响七声，最后总拖着第八声。司礼把珠数过许多次，直到发现镜中的冠比实物多一钗。','原型·新娘彩冠','allclasses','资源型礼冠','法力 +81；精神 +4；生命 +31；物理平减 +4；回避防御 +4','投入集中在技能续航；不提供物攻、物理会心专精；女性可穿限制保留；同档对应另一性别有独立可用路线','transition','server/migrations/000000_init-25.sql:382','server/migrations/000000_init-28.sql:6597',2040,31,2,2,1,5,0,0,true,false,true,true),
('unique',6,2041,'小鸡妹妹帽','未到卯时','小鸡帽里的棉冠每晚会先于公鸡竖起，到了卯时反而塌下。孩子抱着它睡后，总梦见天边还有另一轮太阳。','原型·小鸡妹妹帽','allclasses','初期精神帽','精神 +5；法力 +72；生命 +31；物理平减 +4；回避防御 +4','投入集中在技能续航；不提供物攻、物理会心专精；女性可穿限制保留；同档对应另一性别有独立可用路线','transition','server/migrations/000000_init-25.sql:395','server/migrations/000000_init-28.sql:6608',2041,31,2,2,1,5,0,0,true,false,true,true),
('unique',6,2042,'小鸡哥哥帽','泥里啄金','鸡冠上留着一个细孔，据说曾有小鸡在这里啄到金砂。洗帽时每次都能摸出一粒沙，颜色却从未相同。','原型·小鸡哥哥帽','allclasses','低级精准帽','灵巧 +5；双端物攻 +2；力量 +4；命中 +4；物理会心bp +143','投入集中在物理输出；不提供法攻、法术会心专精；男性可穿限制保留；同档对应另一性别有独立可用路线','transition','server/migrations/000000_init-25.sql:406','server/migrations/000000_init-28.sql:6619',2042,31,1,2,1,5,0,0,true,false,true,true),
('unique',6,2043,'熊猫妹妹帽','黑眼圈借宿','帽上的黑眼圈会随月相变淡，到朔夜几乎不见。店家在后面绣了一颗竹笋，第二天笋尖便朝上长了一针。','原型·熊猫妹妹帽','allclasses','小额魔防头饰','魔防 +18；生命 +124；法术平减 +4；精神 +4；异常抵抗 +6','投入集中在法术承伤；不提供物攻、物理会心专精；女性可穿限制保留；同档对应另一性别有独立可用路线','transition','server/migrations/000000_init-25.sql:419','server/migrations/000000_init-28.sql:6632',2043,31,2,2,1,5,0,0,true,false,true,true),
('unique',6,2044,'熊猫哥哥帽','竹影围头','熊猫帽里夹着一片竹叶，日晒也不枯。移走竹叶之后，帽上的耳朵反而会投出两道很细的竹影。','原型·熊猫哥哥帽','allclasses','早期法力饰物','法力 +81；精神 +4；生命 +31；物理平减 +4；回避防御 +4','投入集中在技能续航；不提供物攻、物理会心专精；男性可穿限制保留；同档对应另一性别有独立可用路线','transition','server/migrations/000000_init-25.sql:430','server/migrations/000000_init-28.sql:6643',2044,31,1,2,1,5,0,0,true,false,true,true),
('unique',6,2060,'图腾头饰','木眼','图腾的第三只眼是木节天然长成，雕师没有动过刀。每次上漆，那只眼便在别的地方重新露出来。','原创·图腾头饰空白底材','allclasses','初期精神图腾','精神 +5；法力 +72；生命 +31；物理平减 +4；回避防御 +4','投入集中在技能续航；不提供物攻、物理会心专精','transition','server/migrations/000000_init-25.sql:611','server/migrations/000000_init-28.sql:6824',2060,31,0,2,1,5,0,0,true,false,true,true),
('unique',6,2061,'兽图腾头饰','咬尾的木兽','兽图腾咬着自己的尾，嘴缝里夹着一粒石籽。取出石籽后兽口仍没张开，只是整块木头明显轻了许多。','原创·兽图腾空白底材','allclasses','低级物抗图腾','物理平减 +5；生命 +163；回避防御 +4；体质 +4；魔防 +14','投入集中在物理承伤；不提供物攻、物理会心专精','transition','server/migrations/000000_init-25.sql:622','server/migrations/000000_init-28.sql:6835',2061,31,0,2,1,5,0,0,true,false,true,true),
('unique',6,2062,'男生帽（舶来品）','海风错纽','舶来男帽的扣眼比纽扣多一个，空眼里总有细小盐粒。缝帽人说那是留给回程的风，不肯替客人补住。','原创·舶来男帽','allclasses','初期准确帽','命中 +5；双端物攻 +2；力量 +4；物理会心bp +143；生命 +31','投入集中在物理输出；不提供法攻、法术会心专精；男性可穿限制保留；同档对应另一性别有独立可用路线','transition','server/migrations/000000_init-25.sql:633','server/migrations/000000_init-28.sql:6846',2062,31,1,2,1,5,0,0,true,false,true,true),
('unique',6,2063,'仕女冠（舶来品）','远国梳齿','仕女冠的梳齿数目不合本地习惯，戴上却从不会松。梳下的每根头发都短了一寸，余下那寸始终找不到。','原创·舶来仕女冠','allclasses','初期法力冠','法力 +81；精神 +4；生命 +31；物理平减 +4；回避防御 +4','投入集中在技能续航；不提供物攻、物理会心专精；女性可穿限制保留；同档对应另一性别有独立可用路线','transition','server/migrations/000000_init-25.sql:645','server/migrations/000000_init-28.sql:6858',2063,31,2,2,1,5,0,0,true,false,true,true),
('unique',6,2101,'长筒鞋','寻泉履','粗皮靴落水后，毛尖全朝同一方向竖起。猎人循着毛向找去，发现上游有一处早已干涸的旧泉眼。','原型·劣皮长筒鞋','allclasses','资源过渡鞋','精神 +7；法力 +6；移动速度% +5；生命 +37；回避防御 +6','支付0.20U给MF，少3.6%总战斗预算；不承担BOSS速度最优承诺','transition','server/migrations/000000_init-25.sql:1074','server/migrations/000000_init-28.sql:7287',2101,31,0,9,7,1,0,0,true,false,true,true),
('unique',6,2102,'铁靴','门内应铁趾','靴头凸起一块铁瘤，走过石路总像有人叩门。夜行人刻意避开石头，回到家仍听见门内传来同样的节奏。','原型·沉重铁靴','allclasses','物理承伤靴','物理平减 +7；生命 +23；回避防御 +7；体质 +7；魔防 +19','投入集中在物理承伤；不提供物攻、物理会心专精','transition','server/migrations/000000_init-25.sql:1085','server/migrations/000000_init-28.sql:7300',2102,31,0,9,14,2,0,0,true,false,true,true),
('unique',6,2103,'精钢之靴','未鸣钢','钢靴薄处近乎透光，逆光看像一片蝉翼。工坊在靴底写下未鸣，每到夏天那两个字就会微微颤动。','原型·轻便精钢靴','allclasses','敏捷过渡靴','敏捷 +12；生命 +9；物理平减 +6；回避防御 +9；体质 +9','投入集中在物理承伤；不提供物攻、物理会心专精','transition','server/migrations/000000_init-25.sql:1097','server/migrations/000000_init-28.sql:7312',2103,31,0,9,21,3,0,0,true,false,true,true),
('unique',6,2104,'白金之靴','压舱银履','船匠将两块压舱白金锻成鞋底，免得修船时被浪掀走。海水退去，他还得请两个徒弟把自己从泥里拔出来。','原型·白金之靴沉重','allclasses','站稳挨打的重靴','回避防御 +21；生命 +11；物理平减 +7；体质 +10；魔防 +21','单系投资只提升匹配的真实伤害包；敌人不匹配时不是全能增伤/减伤','transition','server/migrations/000000_init-25.sql:1110','server/migrations/000000_init-28.sql:7323',2104,31,0,9,28,4,0,0,true,false,true,true),
('unique',6,2105,'荣誉之靴','台阶上的银花','授勋靴在石阶上磨出一朵银花，每层台阶的花都不同。宫门修缮后，鞋底多出一块始终抹不掉的石色。','原型·荣誉之靴','allclasses','生命型礼靴','生命 +178；体质 +11；移动速度% +6；物理平减 +8；法术平减 +8','支付0.40U给MF，少7.3%总战斗预算；不承担BOSS速度最优承诺','transition','server/migrations/000000_init-25.sql:1121','server/migrations/000000_init-28.sql:7334',2105,31,0,9,35,5,0,0,true,false,true,true),
('unique',6,2106,'勇者之靴','踏碎的胆石','勇靴底嵌着一块青石，紧张时会自行发热。旧主人临阵从不看敌人，只低头确认青石是否又裂出新纹。','原型·勇者金属靴','allclasses','42级控制耐受靴以状态抗性和移动舒适度成为纯数值小高货；不用虚构鞋子防御白字。','异常抵抗 +18；生命 +344；魔防 +29；法术平减 +10；精神 +14；移动速度% +18','投入集中在法术承伤；不提供物攻、物理会心专精','highvalue','server/migrations/000000_init-25.sql:1132','server/migrations/000000_init-28.sql:7345',2106,31,0,9,42,6,0,0,true,false,true,true),
('unique',6,2107,'王者之靴','空朝靴印','王者之靴的底纹像一座朝堂，唯独御座没有刻出。走过细灰时，空位里却总会出现一个端坐的人形。','原型·王者权威之靴','allclasses','高精神统御靴','精神 +35；法力 +15；移动速度% +7；生命 +77；回避防御 +15','支付0.50U给MF，少9.1%总战斗预算；不承担BOSS速度最优承诺','transition','server/migrations/000000_init-25.sql:1143','server/migrations/000000_init-28.sql:7356',2107,31,0,9,49,7,0,0,true,false,true,true),
