-- Generated by docs/daoist-endgame/catalog/compile_database_catalog.py.
-- Apply transactionally through the standard migration runner; incremental use requires one transaction.
-- Endgame content catalog. Additive only; no player rows, IDs, rolls or content versions are rewritten.
CREATE TABLE IF NOT EXISTS game_endgame_definitions (
 owner_kind text NOT NULL CHECK(owner_kind IN ('unique','formation')), content_version integer NOT NULL CHECK(content_version IN (0,5,6)), definition_id integer NOT NULL CHECK(definition_id>0),
 base_name text NOT NULL DEFAULT '',
 name text NOT NULL DEFAULT '',
 lore text NOT NULL DEFAULT '',
 lore_root text NOT NULL DEFAULT '',
 role text NOT NULL DEFAULT '',
 identity text NOT NULL DEFAULT '',
 benefit text NOT NULL DEFAULT '',
 tradeoff text NOT NULL DEFAULT '',
 power_tier text NOT NULL DEFAULT '',
 source_arm text NOT NULL DEFAULT '',
 source_desc text NOT NULL DEFAULT '',
 base_id integer NOT NULL DEFAULT 0,
 professions integer NOT NULL DEFAULT 0,
 sex integer NOT NULL DEFAULT 0,
 slot integer NOT NULL DEFAULT 0,
 level_requirement integer NOT NULL DEFAULT 0,
 resource_level integer NOT NULL DEFAULT 0,
 channel integer NOT NULL DEFAULT 0,
 min_level integer NOT NULL DEFAULT 0,
 beginner_allowed boolean NOT NULL DEFAULT false,
 unrestricted boolean NOT NULL DEFAULT false,
 native_drop_eligible boolean NOT NULL DEFAULT false,
 legacy_affix_pool_ready boolean NOT NULL DEFAULT false,
 PRIMARY KEY(owner_kind,content_version,definition_id)
);
CREATE TABLE IF NOT EXISTS game_endgame_affixes (
 owner_kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0),
 attr integer NOT NULL DEFAULT 0,
 value integer NOT NULL DEFAULT 0,
 mode integer NOT NULL DEFAULT 0,
 PRIMARY KEY(owner_kind,content_version,definition_id,ordinal),
 FOREIGN KEY(owner_kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS game_endgame_variable_affixes (
 owner_kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0),
 attr integer NOT NULL DEFAULT 0,
 min integer NOT NULL DEFAULT 0,
 max integer NOT NULL DEFAULT 0,
 PRIMARY KEY(owner_kind,content_version,definition_id,ordinal),
 FOREIGN KEY(owner_kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS game_endgame_local_enhancements (
 owner_kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0),
 attr integer NOT NULL DEFAULT 0,
 percent integer NOT NULL DEFAULT 0,
 min_percent integer NOT NULL DEFAULT 0,
 max_percent integer NOT NULL DEFAULT 0,
 PRIMARY KEY(owner_kind,content_version,definition_id,ordinal),
 FOREIGN KEY(owner_kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS game_endgame_traits (
 owner_kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0),
 kind text NOT NULL DEFAULT '',
 power_bp integer NOT NULL DEFAULT 0,
 threshold_pct integer NOT NULL DEFAULT 0,
 skill_id integer NOT NULL DEFAULT 0,
 skill_name text NOT NULL DEFAULT '',
 PRIMARY KEY(owner_kind,content_version,definition_id,ordinal),
 FOREIGN KEY(owner_kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS game_endgame_reserved_skills (
 owner_kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0),
 scope text NOT NULL DEFAULT '',
 target text NOT NULL DEFAULT '',
 levels integer NOT NULL DEFAULT 0,
 PRIMARY KEY(owner_kind,content_version,definition_id,ordinal),
 FOREIGN KEY(owner_kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS game_endgame_skill_bonuses (
 owner_kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0),
 scope text NOT NULL DEFAULT '',
 profession integer NOT NULL DEFAULT 0,
 branch text NOT NULL DEFAULT '',
 school text NOT NULL DEFAULT '',
 skill_id integer NOT NULL DEFAULT 0,
 levels bigint NOT NULL DEFAULT 0,
 PRIMARY KEY(owner_kind,content_version,definition_id,ordinal),
 FOREIGN KEY(owner_kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS game_endgame_typed_effects (
 owner_kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0),
 kind text NOT NULL DEFAULT '',
 variant_id text NOT NULL DEFAULT '',
 element text NOT NULL DEFAULT '',
 value integer NOT NULL DEFAULT 0,
 proc_id text NOT NULL DEFAULT '',
 proc_trigger text NOT NULL DEFAULT '',
 proc_skill_id integer NOT NULL DEFAULT 0,
 proc_fixed_rank integer NOT NULL DEFAULT 0,
 proc_chance_bp integer NOT NULL DEFAULT 0,
 proc_icd_ms integer NOT NULL DEFAULT 0,
 proc_shared_group text NOT NULL DEFAULT '',
 proc_payload text NOT NULL DEFAULT '',
 proc_target_rule text NOT NULL DEFAULT '',
 proc_max_targets integer NOT NULL DEFAULT 0,
 proc_scale_bp integer NOT NULL DEFAULT 0,
