 aura_visual_key text NOT NULL DEFAULT '',
 aura_priority integer NOT NULL DEFAULT 0,
 aura_pvp_scale_bp integer NOT NULL DEFAULT 0,
 PRIMARY KEY(owner_kind,content_version,definition_id,ordinal),
 FOREIGN KEY(owner_kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS game_endgame_runes (
 owner_kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0),
 item_id integer NOT NULL DEFAULT 0,
 PRIMARY KEY(owner_kind,content_version,definition_id,ordinal),
 FOREIGN KEY(owner_kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS game_endgame_slots (
 owner_kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0),
 slot integer NOT NULL DEFAULT 0,
 PRIMARY KEY(owner_kind,content_version,definition_id,ordinal),
 FOREIGN KEY(owner_kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE
