CREATE TABLE IF NOT EXISTS game_endgame_rune_rules (item_id integer PRIMARY KEY, mansion text NOT NULL, quadrant text NOT NULL, regeneration_interval_ms integer NOT NULL CHECK(regeneration_interval_ms=0 OR (regeneration_interval_ms BETWEEN 100 AND 60000 AND regeneration_interval_ms%100=0)));
CREATE OR REPLACE VIEW game_endgame_catalog AS SELECT d.owner_kind AS kind,d.content_version,d.definition_id,jsonb_build_object('ID',d.definition_id,'BaseName',d.base_name,'Name',d.name,'Lore',d.lore,'LoreRoot',d.lore_root,'Role',d.role,'Identity',d.identity,'Benefit',d.benefit,'Tradeoff',d.tradeoff,'PowerTier',d.power_tier,'SourceArm',d.source_arm,'SourceDesc',d.source_desc,'BaseID',d.base_id,'Professions',d.professions,'Sex',d.sex,'Slot',d.slot,'LevelRequirement',d.level_requirement,'ResourceLevel',d.resource_level,'Channel',d.channel,'MinLevel',d.min_level,'BeginnerAllowed',d.beginner_allowed,'Unrestricted',d.unrestricted,'NativeDropEligible',d.native_drop_eligible,'LegacyAffixPoolReady',d.legacy_affix_pool_ready)||jsonb_build_object('Affixes',COALESCE((SELECT jsonb_agg(jsonb_build_object('Attr',x.attr,'Value',x.value,'Mode',x.mode) ORDER BY x.ordinal) FROM game_endgame_affixes x WHERE (x.owner_kind,x.content_version,x.definition_id)=(d.owner_kind,d.content_version,d.definition_id)),'[]'::jsonb))||jsonb_build_object('VariableAffixes',COALESCE((SELECT jsonb_agg(jsonb_build_object('Attr',x.attr,'Min',x.min,'Max',x.max) ORDER BY x.ordinal) FROM game_endgame_variable_affixes x WHERE (x.owner_kind,x.content_version,x.definition_id)=(d.owner_kind,d.content_version,d.definition_id)),'[]'::jsonb))||jsonb_build_object('LocalEnhancements',COALESCE((SELECT jsonb_agg(jsonb_build_object('Attr',x.attr,'Percent',x.percent,'MinPercent',x.min_percent,'MaxPercent',x.max_percent) ORDER BY x.ordinal) FROM game_endgame_local_enhancements x WHERE (x.owner_kind,x.content_version,x.definition_id)=(d.owner_kind,d.content_version,d.definition_id)),'[]'::jsonb))||jsonb_build_object('Traits',COALESCE((SELECT jsonb_agg(jsonb_build_object('Kind',x.kind,'PowerBP',x.power_bp,'ThresholdPct',x.threshold_pct,'SkillID',x.skill_id,'SkillName',x.skill_name) ORDER BY x.ordinal) FROM game_endgame_traits x WHERE (x.owner_kind,x.content_version,x.definition_id)=(d.owner_kind,d.content_version,d.definition_id)),'[]'::jsonb))||jsonb_build_object('ReservedSkills',COALESCE((SELECT jsonb_agg(jsonb_build_object('Scope',x.scope,'Target',x.target,'Levels',x.levels) ORDER BY x.ordinal) FROM game_endgame_reserved_skills x WHERE (x.owner_kind,x.content_version,x.definition_id)=(d.owner_kind,d.content_version,d.definition_id)),'[]'::jsonb))||jsonb_build_object('SkillBonuses',COALESCE((SELECT jsonb_agg(jsonb_build_object('scope',x.scope,'profession',x.profession,'branch',x.branch,'school',x.school,'skillID',x.skill_id,'levels',x.levels) ORDER BY x.ordinal) FROM game_endgame_skill_bonuses x WHERE (x.owner_kind,x.content_version,x.definition_id)=(d.owner_kind,d.content_version,d.definition_id)),'[]'::jsonb))||jsonb_build_object('TypedEffects',COALESCE((SELECT jsonb_agg(jsonb_build_object('kind',x.kind,'variantID',x.variant_id,'element',x.element,'value',x.value)||jsonb_build_object('proc',CASE WHEN x.proc_id='' THEN NULL ELSE jsonb_build_object('iD',x.proc_id,'trigger',x.proc_trigger,'skillID',x.proc_skill_id,'fixedRank',x.proc_fixed_rank,'chanceBP',x.proc_chance_bp,'iCDMS',x.proc_icd_ms,'sharedGroup',x.proc_shared_group,'payload',x.proc_payload,'targetRule',x.proc_target_rule,'maxTargets',x.proc_max_targets,'scaleBP',x.proc_scale_bp,'pVPScaleBP',x.proc_pvp_scale_bp,'hPBelowPct',x.proc_hp_below_pct,'requireMagic',x.proc_require_magic,'priority',x.proc_priority,'visualKey',x.proc_visual_key) END,'aura',CASE WHEN x.aura_id='' THEN NULL ELSE jsonb_build_object('iD',x.aura_id,'fixedRank',x.aura_fixed_rank,'family',x.aura_family,'modifier',x.aura_modifier,'element',x.aura_element,'value',x.aura_value,'radiusPX',x.aura_radius_px,'refreshMS',x.aura_refresh_ms,'leaseMS',x.aura_lease_ms,'maxPlayers',x.aura_max_players,'includeActivePet',x.aura_include_active_pet,'visualKey',x.aura_visual_key,'priority',x.aura_priority,'pVPScaleBP',x.aura_pvp_scale_bp) END) ORDER BY x.ordinal) FROM game_endgame_typed_effects x WHERE (x.owner_kind,x.content_version,x.definition_id)=(d.owner_kind,d.content_version,d.definition_id)),'[]'::jsonb))||jsonb_build_object('Runes',COALESCE((SELECT jsonb_agg(x.item_id ORDER BY x.ordinal) FROM game_endgame_runes x WHERE (x.owner_kind,x.content_version,x.definition_id)=(d.owner_kind,d.content_version,d.definition_id)),'[]'::jsonb))||jsonb_build_object('Slots',COALESCE((SELECT jsonb_agg(x.slot ORDER BY x.ordinal) FROM game_endgame_slots x WHERE (x.owner_kind,x.content_version,x.definition_id)=(d.owner_kind,d.content_version,d.definition_id)),'[]'::jsonb)) AS definition FROM game_endgame_definitions d;
CREATE TABLE IF NOT EXISTS game_equipment_skill_variants (
 id text NOT NULL DEFAULT '',
 name text NOT NULL DEFAULT '',
 description text NOT NULL DEFAULT '',
 skill_id integer NOT NULL DEFAULT 0,
 profession integer NOT NULL DEFAULT 0,
 max_targets integer NOT NULL DEFAULT 0,
 behavior text NOT NULL DEFAULT '',
 damage_percent integer NOT NULL DEFAULT 0,
 secondary_damage_percent integer NOT NULL DEFAULT 0,
 secondary_no_statuses boolean NOT NULL DEFAULT false,
 secondary_no_knockback boolean NOT NULL DEFAULT false,
 min_cooldown_ms integer NOT NULL DEFAULT 0,
 trap_skill_id integer NOT NULL DEFAULT 0,
 trap_search_radius integer NOT NULL DEFAULT 0,
 trap_min_radius integer NOT NULL DEFAULT 0,
 trap_max_targets integer NOT NULL DEFAULT 0,
 immediate_heal_percent integer NOT NULL DEFAULT 0,
 delayed_heal_percent integer NOT NULL DEFAULT 0,
 delay_ms integer NOT NULL DEFAULT 0,
 area_shape integer NOT NULL DEFAULT 0,
 area_center integer NOT NULL DEFAULT 0,
 area_radius integer NOT NULL DEFAULT 0,
 area_angle integer NOT NULL DEFAULT 0,
 area_length integer NOT NULL DEFAULT 0,
 area_width integer NOT NULL DEFAULT 0, PRIMARY KEY(id)
);
CREATE OR REPLACE VIEW game_equipment_skill_variant_catalog AS SELECT id,jsonb_build_object('ID',x.id,'Name',x.name,'Description',x.description,'SkillID',x.skill_id,'Profession',x.profession,'MaxTargets',x.max_targets,'Behavior',x.behavior)||jsonb_build_object('Params',jsonb_build_object('DamagePercent',x.damage_percent,'SecondaryDamagePercent',x.secondary_damage_percent,'SecondaryNoStatuses',x.secondary_no_statuses,'SecondaryNoKnockback',x.secondary_no_knockback,'MinCooldownMS',x.min_cooldown_ms,'TrapSkillID',x.trap_skill_id,'TrapSearchRadius',x.trap_search_radius,'TrapMinRadius',x.trap_min_radius,'TrapMaxTargets',x.trap_max_targets,'ImmediateHealPercent',x.immediate_heal_percent,'DelayedHealPercent',x.delayed_heal_percent,'DelayMS',x.delay_ms)||jsonb_build_object('Area',jsonb_build_object('Shape',x.area_shape,'Center',x.area_center,'Radius',x.area_radius,'Angle',x.area_angle,'Length',x.area_length,'Width',x.area_width))) AS definition FROM game_equipment_skill_variants x;
CREATE TABLE IF NOT EXISTS game_endgame_catalog_manifest(kind text NOT NULL, content_version integer NOT NULL, expected_count integer NOT NULL CHECK(expected_count>0), PRIMARY KEY(kind,content_version));
CREATE TABLE IF NOT EXISTS game_endgame_definition_manifest(kind text NOT NULL, content_version integer NOT NULL, definition_id integer NOT NULL, section text NOT NULL, expected_rows integer NOT NULL CHECK(expected_rows>=0), PRIMARY KEY(kind,content_version,definition_id,section), FOREIGN KEY(kind,content_version,definition_id) REFERENCES game_endgame_definitions(owner_kind,content_version,definition_id) ON DELETE CASCADE);
